import { readFileSync, writeFileSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import { transformSync } from "esbuild";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const mcpAppsHtmlPath = join(
  __dirname,
  "../server/routes/apps/mcp-apps/sandbox-proxy.html",
);
const outputTsPath = join(
  __dirname,
  "../server/routes/apps/SandboxProxyHtml.bundled.ts",
);

try {
  const policy = transformSync(
    readFileSync(join(__dirname, "../server/utils/sandbox-csp-policy.ts"), "utf-8"),
    { loader: "ts", format: "iife", globalName: "SandboxCspPolicy" },
  ).code.trim();
  const template = readFileSync(mcpAppsHtmlPath, "utf-8");
  const marker = "/*__MCPJAM_CSP_POLICY__*/";
  if (template.split(marker).length !== 2) {
    throw new Error("Sandbox proxy template must contain exactly one policy marker");
  }
  const mcpAppsHtml = template.replace(marker, () => policy);

  const outputContent = `// This file is auto-generated by scripts/bundle-sandbox-proxy-html.js
// Do not edit directly - modify sandbox-proxy.html or sandbox-csp-policy.ts instead

export const MCP_APPS_SANDBOX_PROXY_HTML = ${JSON.stringify(mcpAppsHtml)};
`;

  if (process.argv.includes("--check")) {
    if (readFileSync(outputTsPath, "utf-8") !== outputContent) {
      throw new Error(
        "Sandbox proxy bundle is stale; run npm run bundle:sandbox-proxies",
      );
    }
  } else {
    writeFileSync(outputTsPath, outputContent);
  }
  process.stdout.write("Successfully bundled sandbox proxy HTML files\n");
} catch (error) {
  process.stderr.write(
    `Failed to bundle sandbox proxy HTML files: ${error instanceof Error ? error.message : String(error)}\n`,
  );
  process.exit(1);
}
